/* UI for the browser-only Workflow Studio. No backend or network side effects. */
const STORE='payobook-workflow-design-v2';
let persisted={drafts:{},versions:[],components:[],scenarios:[],runs:[]};
try{
 const raw=JSON.parse(localStorage.getItem(STORE)||'null');
 if(raw?.drafts&&Array.isArray(raw.versions))persisted={...persisted,...raw};
 else{const old=JSON.parse(localStorage.getItem('payobook-workflow-design-v1')||'null');if(old?.drafts){Object.entries(old.drafts).forEach(([key,d])=>persisted.drafts[key]=migrate(d));persisted.versions=(old.versions||[]).map(v=>({...v,number:v.number||v.version||1,draft:migrate(v.draft)})).sort((a,b)=>b.number-a.number);}}
}catch(e){/* Retain the original storage; load a usable sample if it is unreadable. */}
let state={template:'expense',draft:null,selected:'manager',view:'journey',mode:'design',history:[],redo:[],zoom:.7,search:'',run:null,pending:null,viewer:'Assigned participant',facts:{...SAMPLE},suite:null};
state.draft=persisted.drafts.expense?migrate(persisted.drafts.expense):freshDraft('expense');
const draft=()=>state.draft, nodes=()=>draft().nodes, current=()=>byId(draft(),state.selected)||nodes()[0];
const definitionErrors=()=>issues(draft()).filter(i=>i.severity==='error');
function save(){persisted.drafts[state.template]=clone(draft());try{localStorage.setItem(STORE,JSON.stringify(persisted));$('#draft-status').textContent='Saved in this browser'}catch(e){$('#draft-status').textContent='Storage full · export to keep this draft'}$('#save-status').textContent='Local draft';}
function checkpoint(){state.history.push(clone(draft()));if(state.history.length>40)state.history.shift();state.redo=[];}
function change(fn){checkpoint();fn();draft().revision++;state.run=null;state.suite=null;save();render();}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function openModal(title,eyebrow,html){$('#modal-title').textContent=title;$('#modal-eyebrow').textContent=eyebrow;$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();$('#modal').scrollTop=0;}
function closeModal(){$('#modal').close();}
function setMode(mode){state.mode=mode;closeModal();render();}
function selectNode(id){state.selected=id;state.mode='design';closeModal();render();requestAnimationFrame(()=>{$(`[data-node="${id}"]`)?.scrollIntoView({block:'nearest',inline:'nearest',behavior:'smooth'})});}
function nodeSummary(n){
 if(n.type==='trigger')return draft().event;
 if(n.type==='branch')return `${n.branches.length} named routes · first match wins`;
 if(n.type==='parallel')return `${n.branches.length} independent routes · ${n.join==='all'?'wait for all':'first completed wins'}`;
 if(n.type==='subprocess')return `${n.steps.length} steps · ${n.component.name} v${n.component.version}`;
 if(n.type==='policy')return `${n.rows.length} policy rows · unique match + fallback`;
 if(HUMAN.includes(n.type))return `${n.owner} · ${n.due} working days`;
 if(n.type==='email')return `To ${n.recipient.toLowerCase()} · after completion`;
 if(n.type==='state')return `Business action → ${n.state}`;
 if(n.type==='wait')return `Wait ${n.hours} hours`;
 return `${n.service||'Service desk'} · ${n.retry} retries`;
}
function nodeBadge(n){const errors=issues(draft()).filter(i=>i.id===n.id&&i.severity==='error');if(errors.length)return `<span class="node-readiness needs">! ${errors.length} to resolve</span>`;return `<span class="node-readiness">✓ Ready</span>`;}
function nodeCard(n,graph=false){const runStatus=state.run?.states[n.id]||'';return `<button class="step type-${n.type} ${graph?'graph-node':''} ${state.selected===n.id?'selected':''} ${runStatus==='waiting'?'running':''}" data-node="${n.id}" ${graph?'':`draggable="${n.type!=='trigger'}"`} aria-label="Configure ${esc(n.title)}"><div class="step-top">${icons(n.type)}<div><div class="step-title">${esc(n.title)}</div><div class="step-subtitle">${TYPES[n.type].name}</div></div><span class="grip">⠿</span></div><div class="step-detail">${esc(nodeSummary(n))}</div>${graph?'':`<div class="step-meta">${nodeBadge(n)}${n.notes?'<span class="mini-note-icon" title="This step has a design note">☷ Note</span>':''}</div>`}</button>`;}
function render(){
 const t=TEMPLATES[state.template],problems=issues(draft()),errors=problems.filter(i=>i.severity==='error');
 $('#process-title').textContent=draft().name;$('#process-subtitle').textContent=`${t.domain} · ${nodes().length} steps · one shared definition`;
 $('#process-icon').textContent=t.icon;$('#trigger-summary').textContent=draft().event;$('#scope-summary').textContent=draft().scope.rules.length?`${draft().scope.rules.length} eligibility filters`:'All departments';
 $$('[data-mode]').forEach(b=>{b.classList.toggle('selected',b.dataset.mode===state.mode);b.setAttribute('aria-pressed',String(b.dataset.mode===state.mode))});
 $$('[data-view]').forEach(b=>{b.classList.toggle('selected',b.dataset.view===state.view);b.setAttribute('aria-pressed',String(b.dataset.view===state.view))});
 $('#readiness').innerHTML=errors.length?`<span class="issue-dot"></span>${errors.length} to resolve`:`<span class="ready-dot"></span>Ready to rehearse`;
 $('#design-panel').hidden=state.mode!=='design';$('#mode-content').hidden=state.mode==='design';
 if(state.mode==='design'){
  renderPalette();const views={journey:['A journey everyone can follow','Add work to a phase or a named route. Expand detail when you need it.'],canvas:['Every route. Every rejoin.','Arrange cards; connections come from the structured workflow.'],blueprint:['Ownership across the journey','Drag human work between people. Group membership remains intact.']};
  $('#view-title').textContent=views[state.view][0];$('#view-hint').textContent=views[state.view][1];
  $('#workflow-summary').textContent=`${draft().stages.length} phases · ${nodes().filter(n=>GROUPS.includes(n.type)).length} groups · ${nodes().filter(n=>HUMAN.includes(n.type)).length} human steps`;
  if(state.view==='journey')renderJourney();else if(state.view==='canvas')renderCanvas();else renderBlueprint();renderInspector();bindDrag();
 }else if(state.mode==='rehearse')renderRehearsal();else if(state.mode==='review')renderReview();else renderMonitor();
}
function renderPalette(){const entries=Object.entries(TYPES).filter(([k,t])=>!['trigger','condition'].includes(k)&&(!state.search||`${t.name} ${t.description}`.toLowerCase().includes(state.search.toLowerCase())));$('#palette').innerHTML=entries.map(([k,t])=>`<button class="palette-item" data-block="${k}" draggable="true" aria-label="Add ${t.name}">${icons(k)}<span>${t.name}</span><small>⠿</small></button>`).join('')||'<p class="hint">No matching blocks.</p>';}
function sequenceHTML(ids,key,stage,depth=0){return `<div class="route-sequence" data-drop-key="${key}" data-drop-stage="${stage}">${ids.map(id=>{const n=byId(draft(),id);if(!n)return'';const group=GROUPS.includes(n.type);return `<div class="node-wrapper" data-wrapper="${n.id}">${nodeCard(n)}${group?`<div class="group-controls"><button data-action="toggle-group" data-id="${n.id}" class="text-btn">${n.collapsed?'Expand':'Collapse'} ${n.type==='subprocess'?'component':'routes'} ${n.collapsed?'⌄':'⌃'}</button><button class="text-btn" data-action="save-component" data-id="${n.id}">Save as component</button></div>${n.collapsed?`<div class="collapsed-note">${n.branches?`${n.branches.length} routes`:`${n.steps.length} steps`} · detail preserved</div>`:n.branches?`<div class="branch-columns" style="--branches:${n.branches.length}">${n.branches.map(b=>`<section class="route-container"><div class="route-label"><b>${esc(b.label)}</b><small>${n.type==='parallel'?'Runs independently':esc(routeText(b.condition,state.template))}</small></div>${sequenceHTML(b.steps,b.id,n.stage,depth+1)}</section>`).join('')}</div>`:`<div class="component-body">${sequenceHTML(n.steps,n.id,n.stage,depth+1)}</div>`}<div class="join-pill">${n.type==='parallel'?'⑂ '+(n.join==='all'?'Wait for all routes':'First completed route; cancel the rest'):'⇢ Rejoin and continue'}</div>`:''}</div>`}).join('')}<button class="drop-add" data-action="add" data-key="${key}" data-stage="${stage}">＋ ${depth?'Add to this route':'What happens next?'}</button></div>`;}
function renderJourney(){$('#workarea').innerHTML=`<div class="journey">${draft().stages.map((s,i)=>`<section class="stage"><div class="stage-label"><span class="stage-number">0${i+1}</span><strong>${esc(s.name)}</strong><span class="phase-status">Record label · ${esc(s.state)}</span><button class="stage-dots" data-action="stage" data-index="${i}" aria-label="Edit ${esc(s.name)} phase">⋯</button></div>${sequenceHTML(draft().order.filter(id=>byId(draft(),id).stage===i),'main',i)}</section>`).join('')}</div>`;}
let canvasSize={w:800,h:900};
function layoutGraph(){
 const positions={};function width(ids){return Math.max(240,...ids.map(id=>{const n=byId(draft(),id);return n.branches?n.branches.reduce((a,b)=>a+width(b.steps),0)+30*(n.branches.length-1):n.steps?width(n.steps):240}))}
 function place(ids,cx,y){for(const id of ids){const n=byId(draft(),id);positions[id]={x:cx-100,y};y+=125;
  if(GROUPS.includes(n.type)){const bs=n.branches||[{steps:n.steps}],ws=bs.map(b=>width(b.steps)),total=ws.reduce((a,b)=>a+b,0)+30*(bs.length-1);let left=cx-total/2,max=y;
   bs.forEach((b,i)=>{max=Math.max(max,place(b.steps,left+ws[i]/2,y+20));left+=ws[i]+30});positions[id+'__join']={x:cx-90,y:max+10};y=max+95;
  }}return y;}
 const w=Math.max(650,width(draft().order)+80),h=place(draft().order,w/2,75)+50;
 canvasSize={w,h};return positions;
}
function renderCanvas(){const plan=compile(draft()),pos=layoutGraph();plan.nodes.forEach(n=>{if(!n.virtual&&!byId(draft(),n.id).pos)byId(draft(),n.id).pos=pos[n.id]});$('#workarea').innerHTML=`<div class="canvas-wrap"><div class="canvas-tools"><button data-action="zoom-out" aria-label="Zoom out">−</button><button data-action="zoom-reset">${Math.round(state.zoom*100)}%</button><button data-action="zoom-in" aria-label="Zoom in">＋</button><button data-action="layout">Auto arrange</button><button data-action="fit">Fit width</button></div><div class="canvas-extent" style="width:${canvasSize.w*state.zoom}px;height:${canvasSize.h*state.zoom}px"><div class="canvas-surface" style="width:${canvasSize.w}px;height:${canvasSize.h}px;transform:scale(${state.zoom})"><svg class="canvas-svg" style="width:${canvasSize.w}px;height:${canvasSize.h}px" aria-label="Explicit workflow routes and joins"></svg>${plan.nodes.map(n=>n.virtual?`<button class="graph-join" data-node="${n.parent}" data-join="${n.id}" style="left:${pos[n.id].x}px;top:${pos[n.id].y}px">⑂ ${esc(n.title)}</button>`:nodeCard(byId(draft(),n.id),true)).join('')}</div></div></div>`;positionGraph();}
function positionGraph(){nodes().forEach(n=>{const el=$(`.graph-node[data-node="${n.id}"]`);if(el&&n.pos){el.style.left=n.pos.x+'px';el.style.top=n.pos.y+'px'}});drawEdges();}
function drawEdges(){const svg=$('.canvas-svg');if(!svg)return;const plan=compile(draft()),pos=layoutGraph();svg.innerHTML=`<defs><marker id="arrow" viewBox="0 0 8 8" refX="7" refY="4" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0 L8 4 L0 8Z" fill="#ab9bc4"/></marker></defs>`+plan.edges.map(e=>{const a=byId(draft(),e.from),b=byId(draft(),e.to),pa=a?.pos||pos[e.from],pb=b?.pos||pos[e.to],height=a?($(`.graph-node[data-node="${e.from}"]`)?.offsetHeight||96):40;const x1=pa.x+(a?100:90),y1=pa.y+height,x2=pb.x+(b?100:90),y2=pb.y,mid=(y1+y2)/2;return `<path d="M${x1} ${y1} C${x1} ${mid},${x2} ${mid},${x2} ${y2}" stroke="${e.kind==='parallel'?'#70a79d':'#b6a8c7'}" stroke-width="1.7" fill="none" marker-end="url(#arrow)"/>${e.label&&e.label!=='Continue'?`<text x="${(x1+x2)/2+8}" y="${mid-6}" fill="#8c759d" font-size="10">${esc(e.label)}</text>`:''}`}).join('');}
function renderBlueprint(){const roles=[...new Set(['Employee',...ordered(draft()).filter(n=>HUMAN.includes(n.type)).map(n=>n.owner),'System'])],columns=`105px repeat(${draft().stages.length},minmax(170px,1fr))`;$('#workarea').innerHTML=`<div class="lane-board"><div class="lane-headers" style="grid-template-columns:${columns}"><div>RESPONSIBILITY</div>${draft().stages.map(s=>`<div>${esc(s.name)}</div>`).join('')}</div>${roles.map(role=>`<div class="lane-row" style="grid-template-columns:${columns}"><div class="lane-label">◉ ${esc(role)}</div>${draft().stages.map((s,i)=>`<div class="lane-cell" data-drop-stage="${i}" data-owner="${esc(role)}">${ordered(draft()).filter(n=>n.stage===i&&n.owner===role).map(n=>`<button class="lane-card ${n.id===state.selected?'selected':''}" draggable="${n.type!=='trigger'}" data-node="${n.id}">${icons(n.type)}<span>${esc(n.title)}<small>${ancestors(draft(),n.id).map(x=>esc(x.title)).join(' / ')||TYPES[n.type].name}</small></span></button>`).join('')}</div>`).join('')}</div>`).join('')}<div class="board-explainer"><b>Assignment is visible; permission is still checked.</b> Drag a human step to another person in the same phase. To move grouped work to another phase, move the whole group.</div></div>`;}
function renderInspector(){
 const n=current(),parent=containerFor(draft(),n.id)?.parent;let html=field('Step name',input('title',n.title,'text','data-edit="title" maxlength="80"'));
 if(parent)html+=`<div class="mini-note">Inside <button class="text-btn" data-select="${parent.id}">${esc(parent.title)} ↗</button></div>`;
 if(n.type==='trigger')html+=field('Start event',input('event',draft().event,'text','data-event="true"'))+`<button class="button white" data-action="scope">Configure eligibility</button>`;
 if(HUMAN.includes(n.type)){
  html+=field(n.type==='approval'?'Who approves?':'Who does this?',select('owner',PEOPLE.filter(x=>x!=='System'),n.owner,'data-edit="owner"'))+field('Due within working days',input('due',n.due,'number','data-edit="due" min="1" max="90"'));
  if(n.type==='input')html+=field('Ask for this information',input('fieldLabel',n.fieldLabel,'text','data-edit="fieldLabel"'))+field('Instructions',`<textarea data-edit="prompt">${esc(n.prompt)}</textarea>`)+`<label class="check-field"><input type="checkbox" data-edit="required" ${n.required?'checked':''}>Require an answer before continuing</label>`;
  html+=`<button class="button white full" data-action="participant">◉ Preview participant screen</button><details class="advanced"><summary>People, cover & outcomes</summary><label class="check-field"><input type="checkbox" data-edit="delegate" ${n.delegate?'checked':''}>Use valid cover when unavailable</label>${n.type==='approval'?`<label class="check-field"><input type="checkbox" data-edit="independent" ${n.independent?'checked':''}>Require an independent approver</label><div class="outcome-list"><span>Approved → continue</span><span>Rejected → stop</span><span>Needs changes → requester rework</span></div>`:''}<div class="mini-note">Assignment does not grant access. Live company, record and field policies still apply.</div></details>`;
 }
 if(n.type==='branch')html+=`<div class="section-label">FIRST MATCH WINS</div>${n.branches.map((b,i)=>`<div class="route-settings">${field('Route name',input('label',b.label,'text',`data-route="${i}" data-route-prop="label"`))}${b.condition?`${field('When',select('field',[['amount',TEMPLATES[state.template].numeric],['department','Department'],['country','Country']],b.condition.field,`data-route="${i}" data-route-prop="field"`))}<div class="field-row">${field('Comparison',select('op',b.condition.field==='amount'?[['gt','>'],['gte','≥'],['lt','<'],['eq','=']]:[['eq','is'],['ne','is not']],b.condition.op,`data-route="${i}" data-route-prop="op"`))}${field('Value',input('value',b.condition.value,b.condition.field==='amount'?'number':'text',`data-route="${i}" data-route-prop="value"`))}</div>`:'<span class="inline-label">Otherwise · fallback route</span>'}</div>`).join('')}<button class="button white" data-action="add-route">＋ Add conditional route</button>`;
 if(n.type==='parallel')html+=field('Continue when',select('join',[['all','Every route is complete'],['any','First route completes; cancel others']],n.join,'data-edit="join"'))+`<div class="mini-note">Routes can wait independently. The join releases only when this rule is met. “First completed” cancels unfinished routes in this rehearsal.</div>${n.branches.map((b,i)=>field('Route '+(i+1),input('label',b.label,'text',`data-route="${i}" data-route-prop="label"`))).join('')}<button class="button white" data-action="add-route">＋ Add parallel route</button>`;
 if(n.type==='subprocess')html+=`<div class="mini-note"><b>${esc(n.component.name)} · v${n.component.version}</b><br>This instance contains a pinned local copy. Editing it does not change other instances.</div><button class="button white" data-action="save-component" data-id="${n.id}">Save as a new component version</button>`;
 if(n.type==='policy')html+=`<div class="mini-note">Rules use minimum-inclusive, maximum-exclusive ranges. Multiple matching rows are blocked. Unmatched values use the fallback.</div><button class="button primary full" data-action="policy">▤ Edit decision table</button>`+field('Fallback reviewer',select('fallback',PEOPLE.filter(x=>!['System','Employee','Policy result'].includes(x)),n.fallback,'data-edit="fallback"'));
 if(n.type==='email')html+=field('Recipient responsibility',select('recipient',PEOPLE.filter(x=>!['System','Policy result'].includes(x)),n.recipient,'data-edit="recipient"'))+field('Message with live example values',`<textarea id="email-message" data-edit="body" rows="5">${esc(n.body)}</textarea>`)+`<div class="token-label">INSERT A VALUE</div><div class="token-list">${availableTokens(draft(),n.id).map(t=>`<button class="token" data-insert-token="${esc(t.key)}" title="${esc(t.type+' · '+t.value)}">${esc(t.label)} <small>${t.type}</small></button>`).join('')}</div><div class="message-preview"><b>Rendered sample</b><p>${esc(sampleMessage(n))}</p></div><button class="text-btn" data-action="data">Inspect sources & types →</button>`;
 if(n.type==='state')html+=field('Proposed status',select('state',[...new Set([...draft().stages.map(s=>s.state),'Approved','Rejected','Completed',n.state])],n.state,'data-edit="state"'))+`<div class="mini-note">A live adapter must call a permitted business transition. Phase labels do not create model state values.</div>`;
 if(n.type==='wait')html+=field('Wait in hours',input('hours',n.hours,'number','data-edit="hours" min="1" max="720"'));
 if(n.type==='webhook')html+=field('Connected service concept',select('service',['Service desk','HR directory','Finance system'],n.service||'Service desk','data-edit="service"'))+`<div class="mini-note">No external call is made. Production requires an authorised connector, typed inputs and secure credentials.</div>`;
 if(['email','webhook'].includes(n.type))html+=`<details class="advanced"><summary>Failure handling</summary>${field('Maximum manual example retries',input('retry',n.retry,'number','data-edit="retry" min="0" max="5"'))}<p class="hint">Inject a failure in Rehearse, then retry the failed action. Production needs backoff, deduplication and an owner for exhausted retries.</p></details>`;
 html+=`<details class="advanced"><summary>Design note & placement</summary>${field('Why this step exists',`<textarea data-edit="notes" maxlength="500">${esc(n.notes)}</textarea>`)}${n.type!=='trigger'?field('Phase',select('stage',draft().stages.map((s,i)=>[i,s.name]),n.stage,`data-edit="stage" ${parent?'disabled':''}`)):''}</details>`;
 if(n.type!=='trigger')html+=`<div class="inspector-actions"><button class="button white" data-action="move-up">↑ Earlier</button><button class="button white" data-action="move-down">↓ Later</button><button class="button white danger" data-action="delete">Remove</button></div>`;
 const problems=issues(draft()).filter(x=>x.id===n.id);$('#inspector').innerHTML=`<div class="panel-heading">STEP SETTINGS</div><div class="inspector-heading">${icons(n.type)}<div><strong>${TYPES[n.type].name}</strong><small>Shared across all three views</small></div></div>${problems.map(p=>`<div class="inline-issue ${p.severity}">${esc(p.text)}</div>`).join('')}${html}`;
}
function sampleMessage(n){const r={facts:{...SAMPLE,amount:TEMPLATES[state.template].value},outputs:{},recordState:'Approved'};previousIds(draft(),n.id).forEach(id=>r.outputs[id]=byId(draft(),id).type==='state'?byId(draft(),id).state:'Sample result');try{return expandMessage(n.body,r)}catch(e){return e.message}}
function addNode(type,key='main',stage=1){const n=makeNode(type,+stage);change(()=>{const c=containers(draft()).find(c=>c.key===key)||containers(draft())[0];n.stage=c.parent?.stage??+stage;nodes().push(n);if(c.key==='main'){const idx=draft().order.findLastIndex(id=>byId(draft(),id).stage<=n.stage)+1;c.ids.splice(Math.max(1,idx),0,n.id)}else c.ids.push(n.id);state.selected=n.id;});closeModal();toast(TYPES[type].name+' added. Configure it in Step settings.');}
function setStage(id,stage){descendants(draft(),id).forEach(k=>{const n=byId(draft(),k);n.stage=stage;delete n.pos});}
function moveNode(id,key,stage,before=null,owner=null){const n=byId(draft(),id);if(!n||n.type==='trigger')return;const from=containerFor(draft(),id),to=containers(draft()).find(c=>c.key===key)||containers(draft())[0];if(to.parent&&descendants(draft(),id).includes(to.parent.id)){toast('A group cannot contain itself.');return;}if(owner){if(!HUMAN.includes(n.type)){toast('Automated steps stay with System.');return;}if(owner==='System'){toast('Human steps need a person or responsibility.');return;}if(from.parent&&+stage!==n.stage){toast('Move the parent group to change its phase.');return;}}
 change(()=>{if(owner&&from.parent){n.owner=owner;return;}from.ids.splice(from.ids.indexOf(id),1);let idx=before?to.ids.indexOf(before):-1;if(idx<0)idx=to.key==='main'?to.ids.findLastIndex(k=>byId(draft(),k).stage<=+stage)+1:to.ids.length;if(to.key==='main')idx=Math.max(1,idx);to.ids.splice(idx,0,id);setStage(id,to.parent?.stage??+stage);if(owner)n.owner=owner;});}
let dragData=null,dragged=false;
function bindDrag(){
 $$('[draggable="true"]').forEach(el=>{el.addEventListener('dragstart',e=>{e.stopPropagation();dragData=el.dataset.block?{type:el.dataset.block}:{id:el.dataset.node};e.dataTransfer.setData('text/plain',JSON.stringify(dragData));e.dataTransfer.effectAllowed='move'});el.addEventListener('dragend',()=>{dragData=null;$$('.drop-target').forEach(x=>x.classList.remove('drop-target'))})});
 $$('[data-drop-key],.lane-cell').forEach(zone=>{zone.addEventListener('dragover',e=>{e.preventDefault();e.stopPropagation();zone.classList.add('drop-target')});zone.addEventListener('dragleave',e=>{if(!zone.contains(e.relatedTarget))zone.classList.remove('drop-target')});zone.addEventListener('drop',e=>{e.preventDefault();e.stopPropagation();zone.classList.remove('drop-target');if(!dragData)return;let before=e.target.closest('[data-node]')?.dataset.node;if(before&&containerFor(draft(),before)?.key!==(zone.dataset.dropKey||'main'))before=null;if(dragData.type)addNode(dragData.type,zone.dataset.dropKey||'main',+zone.dataset.dropStage);else if(before!==dragData.id)moveNode(dragData.id,zone.dataset.dropKey||'main',+zone.dataset.dropStage,before,zone.dataset.owner);dragData=null})});
 const canvas=$('.canvas-wrap');if(canvas){canvas.addEventListener('dragover',e=>e.preventDefault());canvas.addEventListener('drop',e=>{e.preventDefault();if(dragData?.type)addNode(dragData.type,'main',current().stage);dragData=null});$$('.graph-node').forEach(el=>el.addEventListener('pointerdown',e=>{if(e.button!==0)return;const n=byId(draft(),el.dataset.node),origin={...n.pos},sx=e.clientX,sy=e.clientY;let changed=false;el.setPointerCapture(e.pointerId);const move=ev=>{const dx=(ev.clientX-sx)/state.zoom,dy=(ev.clientY-sy)/state.zoom;if(!changed&&Math.abs(dx)+Math.abs(dy)>5){checkpoint();changed=true;dragged=true}if(changed){n.pos={x:Math.max(0,Math.min(canvasSize.w-210,origin.x+dx)),y:Math.max(45,Math.min(canvasSize.h-120,origin.y+dy))};positionGraph()}};const end=()=>{el.removeEventListener('pointermove',move);el.removeEventListener('pointerup',end);el.removeEventListener('pointercancel',end);if(changed){save();setTimeout(()=>dragged=false,0)}};el.addEventListener('pointermove',move);el.addEventListener('pointerup',end);el.addEventListener('pointercancel',end)}));}
}

/* Guided rehearsals are deliberately isolated from live business records. */
function rememberRun(){if(!state.run)return;const r=clone(state.run),idx=persisted.runs.findIndex(x=>x.id===r.id);if(idx<0)persisted.runs.unshift(r);else persisted.runs[idx]=r;persisted.runs=persisted.runs.slice(0,25);save();}
function startRun(){state.run=createRun(draft(),state.facts);state.pending=null;state.viewer='Assigned participant';rememberRun();setMode('rehearse');}
function traceHTML(run){return `<div class="trace">${run.trace.map(t=>`<div class="trace-row ${t.status}"><span>${t.status==='done'?'✓':t.status==='waiting'?'◷':t.status==='active'?'⑂':'!'}</span><div><h4>${esc(t.title)}</h4><p>${esc(t.text)}</p></div></div>`).join('')}</div>`;}
function renderRehearsal(){
 const r=state.run,waiting=r?Object.keys(r.states).filter(id=>r.states[id]==='waiting'):[];
 if(!waiting.includes(state.pending))state.pending=waiting[0]||null;
 const n=r&&byId(r.draft,state.pending),actor=n&&actorFor(n,r),allowed=n&&(n.type==='wait'||state.viewer==='Assigned participant'||state.viewer===actor.role);
 let panel='';
 if(!r)panel=`<div class="empty-state"><span>▷</span><h3>Experience the workflow before anyone uses it.</h3><p>Follow a fictional request. Act as the assigned participant, provide evidence and watch the next step open.</p><button class="button primary" data-action="start-run">Start rehearsal →</button></div>`;
 else if(r.status==='waiting')panel=`<div class="participant"><div class="participant-top"><span class="avatar">${n.type==='wait'?'◷':esc(actor.name.split(' ').map(x=>x[0]).join(''))}</span><div><small>${n.type==='wait'?'SIMULATED CLOCK':'YOUR NEXT ACTION'}</small><h3>${esc(n.title)}</h3><p>${n.type==='wait'?`${n.hours} hours until the next step`:esc(actor.name+' · '+actor.role+(actor.cover?' · '+actor.cover:''))}</p></div></div>${n.type!=='wait'?field('View this task as',select('viewer',['Assigned participant','Employee','Their manager','HR partner','Finance approver','IT team'],state.viewer,'data-viewer')):''}${!allowed?'<div class="review-error">This sample role is not assigned to this task. Action controls and record details are hidden. Live permissions must be checked again on submission.</div>':`<div class="sample-record"><span>EXAMPLE RECORD · EXP-2026-018</span><b>${esc(r.facts.employee)}</b><p>${actor?.role==='IT team'?'Equipment request · financial details hidden':`${esc(TEMPLATES[state.template].numeric)}: ${Number(r.facts.amount).toLocaleString()} ${esc(TEMPLATES[state.template].unit)}`} · ${esc(r.facts.department)}</p><small>Sample field policy. Production uses the record's actual access rules.</small></div>${n.type==='input'?`<p class="lead">${esc(n.prompt)}</p>${field(n.fieldLabel+(n.required?' *':''),'<textarea id="participant-answer" placeholder="Enter the requested information"></textarea>')}`:n.type==='approval'?field('Comment (required when requesting changes)','<textarea id="participant-answer" placeholder="Add context for the requester"></textarea>'):''}<div class="participant-actions">${n.type==='approval'?`<button class="button primary" data-respond="approve" data-id="${n.id}">Approve & continue</button><button class="button white" data-respond="return" data-id="${n.id}">Request changes</button><button class="button white danger" data-respond="reject" data-id="${n.id}">Reject</button>`:`<button class="button primary" data-respond="complete" data-id="${n.id}">${n.type==='wait'?'Advance '+n.hours+' hours':n.type==='input'?'Submit information':'Mark complete'} →</button>`}</div><p id="participant-error" class="error-text" role="alert"></p>`}</div>`;
 else if(r.status==='returned')panel=`<div class="participant"><span class="badge">REQUESTER REWORK</span><h3>Make the changes, then resubmit.</h3><p class="lead">${esc(r.trace.at(-1).text)}</p>${field('What did you change?','<textarea id="rework-answer" placeholder="Describe the correction"></textarea>')}<button class="button primary" data-action="resubmit">Resubmit for review →</button><p class="hint">Returns to the same decision. Three rework attempts are allowed in this example.</p></div>`;
 else if(r.status==='blocked')panel=`<div class="participant"><span class="badge needs">NEEDS ATTENTION</span><h3>The workflow paused safely.</h3><p class="lead">${esc(r.trace.at(-1).text)}</p>${Object.keys(r.states).filter(id=>r.states[id]==='failed').map(id=>`<button class="button primary" data-retry="${id}">Retry ${esc(byId(r.draft,id).title)} (${r.attempts[id]||0}/${byId(r.draft,id).retry})</button>`).join('')}<button class="button white" data-action="facts">Change the example</button></div>`;
 else panel=`<div class="empty-state ${r.status==='complete'?'success':''}"><span>${r.status==='complete'?'✓':'◎'}</span><h3>${r.status==='complete'?'The journey is complete.':r.status==='rejected'?'Request rejected.':r.status==='excluded'?'Outside this workflow’s scope.':'Resolve the definition first.'}</h3><p>${r.status==='complete'?`Proposed record status: ${esc(r.recordState)}. All required paths have finished.`:r.status==='rejected'?'Downstream actions were stopped.':esc(r.trace.at(-1)?.text)}</p><button class="button white" data-action="start-run">Rehearse again</button></div>`;
 $('#mode-content').innerHTML=`<div class="mode-heading"><div><span class="eyebrow">02 / REHEARSE</span><h2>A safe space to ask “what happens if?”</h2><p>Fictional records. Real route evaluation. No emails, integrations or record updates.</p></div><button class="button white" data-action="facts">⚙ Example settings</button></div><div class="scenario-ribbon"><span>◉ ${esc(state.facts.employee)}</span><b>${Number(state.facts.amount).toLocaleString()} ${esc(TEMPLATES[state.template].unit)}</b><span>${esc(state.facts.department)} · ${esc(state.facts.country)}</span><span>Manager: ${esc(state.facts.manager)}</span><button class="text-btn" data-action="save-scenario">＋ Save example</button><button class="text-btn" data-action="suite">Run scenario pack →</button></div><div class="rehearsal-grid"><aside class="run-map"><div class="panel-heading">${r?'EXECUTION PROGRESS':'YOUR JOURNEY'}</div>${ordered(r?.draft||draft()).map(x=>`<button class="run-step ${r?.states[x.id]||''} ${state.pending===x.id?'selected':''}" data-pending="${x.id}" ${r?.states[x.id]!=='waiting'?'disabled':''}><span>${r?.states[x.id]==='done'?'✓':r?.states[x.id]==='waiting'?'◷':r?.states[x.id]==='skipped'?'−':'·'}</span><div><b>${esc(x.title)}</b><small>${esc(r?.states[x.id]||'Not started')}</small></div></button>`).join('')}${waiting.length>1?`<div class="mini-note">${waiting.length} tasks are available independently. Select either one above.</div>`:''}</aside><section>${r?`<div class="run-status"><span class="status-pill ${r.status==='blocked'?'proposed':''}">${esc(r.status)}</span><span>${r.clock} simulated hours elapsed</span><button class="text-btn" data-action="start-run">Restart</button></div>`:''}${panel}</section><aside class="run-trace"><div class="panel-heading">WHY THIS HAPPENED</div>${r?traceHTML(r):'<p class="hint">Every rule, assignment, pause and outcome will appear here.</p>'}</aside></div>`;
}
function factsModal(){const f=state.facts;openModal('Try a different situation','FICTIONAL EXAMPLE',`<p class="lead">Change the inputs or inject a failure. Start a new rehearsal to see how your current definition responds.</p><div class="scope-grid">${field(TEMPLATES[state.template].numeric,input('amount',f.amount,'number','id="fact-amount" min="0"'))}${field('Department',select('department',['Operations','Engineering','Finance','People'],f.department,'id="fact-department"'))}${field('Country',select('country',['Australia','Indonesia','India'],f.country,'id="fact-country"'))}${field('Manager availability',select('manager',[['available','Available'],['away','Away · valid cover'],['expired','Away · cover expired']],f.manager,'id="fact-manager"'))}${field('Assigned person’s sample access',select('access',[['allowed','Allowed'],['denied','Denied']],f.access,'id="fact-access"'))}${field('Independent approval',select('actor',[['other','Approver differs from requester'],['self','Approver is the requester']],f.actor,'id="fact-actor"'))}${field('Inject an action failure',select('failure',[['none','None'],['email','First attempt of each email fails'],['webhook','First attempt of each integration fails']],f.failure,'id="fact-failure"'))}</div><div class="modal-actions"><button class="button primary" data-action="apply-facts">Start with these inputs →</button></div>`);}
function scenarioCases(){return [{name:'Standard request',facts:{amount:500}},{name:'Above the threshold',facts:{amount:TEMPLATES[state.template].value}},{name:'Manager covered',facts:{manager:'away'}},{name:'Expired cover',facts:{manager:'expired'}},{name:'Access denied',facts:{access:'denied'}},{name:'Self-approval',facts:{actor:'self'}},{name:'Rejected request',facts:{decision:'reject'}},{name:'Email failure',facts:{failure:'email'}}].map(x=>({...x,facts:{...SAMPLE,amount:TEMPLATES[state.template].value,...x.facts}}));}
function baseline(){return persisted.versions.find(v=>v.draft.template===state.template)?.draft||freshDraft(state.template);}
function runSuite(){const base=baseline(),cases=scenarioCases().map(c=>({...c,expected:outcomeSignature(autoRun(base,c.facts)),source:'Latest saved version / original template'})).concat(persisted.scenarios.filter(s=>s.template===state.template));state.suite=cases.map(c=>{const r=autoRun(draft(),c.facts);return {...c,actual:outcomeSignature(r),status:r.status,pass:c.expected===outcomeSignature(r),trace:r.trace}});setMode('review');}
function renderReview(){const problems=issues(draft()),errors=problems.filter(i=>i.severity==='error'),diff=diffDraft(baseline(),draft()),versions=persisted.versions.filter(v=>v.draft.template===state.template),suite=state.suite;$('#mode-content').innerHTML=`<div class="mode-heading"><div><span class="eyebrow">03 / REVIEW</span><h2>Confidence before a new version.</h2><p>Check the definition, inspect changes and compare outcomes with your saved baseline.</p></div><button class="button primary" data-action="save-version" ${errors.length?'disabled':''}>Save local version ↗</button></div><div class="review-grid"><section class="review-card"><div class="card-heading"><h3>Definition readiness</h3><span class="status-pill ${errors.length?'proposed':''}">${errors.length?errors.length+' errors':'Checks passed'}</span></div>${problems.length?problems.map(i=>`<button class="issue-row ${i.severity}" data-select="${i.id}"><b>${i.severity==='error'?'!':'◌'}</b><span>${esc(i.text)}<small>${esc(byId(draft(),i.id)?.title||'Process settings')} →</small></span></button>`).join(''):'<div class="review-success">✓ Steps, route membership, policy ranges, token availability and assignments are valid for this simulator.</div>'}<p class="hint">Live publication will also require adapter capabilities, actual permissions, business state transitions and deployment approvals.</p></section><section class="review-card"><div class="card-heading"><h3>Changes since ${versions.length?'v'+versions[0].number:'the original template'}</h3><span>${diff.length}</span></div>${diff.length?diff.map(c=>`<button class="diff-row ${c.kind}" ${c.id&&byId(draft(),c.id)?`data-select="${c.id}"`:''}><span class="diff-symbol">${c.kind==='added'?'+':c.kind==='removed'?'−':'~'}</span><div><b>${esc(c.title)}</b><p>${esc(c.text)}</p></div></button>`).join(''):'<p class="blank">No definition changes. Card positioning is presentation only.</p>'}</section></div><section class="review-card suite-card"><div class="card-heading"><div><h3>Scenario regression pack</h3><p class="hint">Eight edge cases plus your saved examples. Changed outcomes need review; they are not automatically bugs.</p></div><button class="button white" data-action="suite">${suite?'Run again':'Run comparison'} ▷</button></div>${suite?`<table class="detail-table"><thead><tr><th>Example</th><th>Result now</th><th>Compared with baseline</th><th></th></tr></thead><tbody>${suite.map((s,i)=>`<tr><td><b>${esc(s.name)}</b></td><td>${esc(s.status)}</td><td><span class="status-pill ${s.pass?'':'proposed'}">${s.pass?'Same outcome':'Outcome changed'}</span></td><td><button class="text-btn" data-scenario-detail="${i}">Inspect trace →</button></td></tr>`).join('')}</tbody></table>`:'<div class="blank">Exercise routes, delegation, rejection, access and injected failures against the baseline.</div>'}</section><section class="review-card"><div class="card-heading"><h3>Local version history</h3><span>${versions.length} snapshots</span></div>${versions.map(v=>`<div class="history-item"><div><b>v${v.number} · ${esc(v.note||'Workflow snapshot')}</b><p>${new Date(v.at).toLocaleString()} · ${v.draft.nodes.length} steps</p></div><button class="button white" data-restore="${v.id}">Restore as draft</button></div>`).join('')||'<p class="hint">Save an immutable local snapshot after resolving definition errors. It does not publish to production.</p>'}</section>`;}
function renderMonitor(){const runs=persisted.runs.filter(r=>r.draft.template===state.template),completed=runs.filter(r=>r.status==='complete').length,blocked=runs.filter(r=>r.status==='blocked').length;$('#mode-content').innerHTML=`<div class="mode-heading"><div><span class="eyebrow">04 / MONITOR</span><h2>Understand every pause and outcome.</h2><p>Only rehearsals saved in this browser are shown. This is not production activity.</p></div><button class="button white" data-mode="rehearse">New rehearsal ▷</button></div><div class="metric-row"><div><b>${runs.length}</b><span>Local rehearsals</span></div><div><b>${completed}</b><span>Completed</span></div><div><b>${blocked}</b><span>Blocked</span></div><div><b>${runs.filter(r=>r.status==='waiting').length}</b><span>Waiting for a person / timer</span></div></div><section class="review-card">${runs.length?`<table class="detail-table"><thead><tr><th>Rehearsal</th><th>Example</th><th>Status</th><th>Latest event</th><th></th></tr></thead><tbody>${runs.map(r=>`<tr><td>${new Date(r.at).toLocaleString()}</td><td>${Number(r.facts.amount).toLocaleString()} · ${esc(r.facts.department)}</td><td><span class="status-pill ${r.status==='blocked'?'proposed':''}">${esc(r.status)}</span></td><td>${esc(r.trace.at(-1)?.title)}</td><td><button class="text-btn" data-run-detail="${r.id}">Trace ↗</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty-state"><span>◷</span><h3>Run your first rehearsal.</h3><p>Completed steps, pauses, retries and decisions will be visible here.</p><button class="button primary" data-action="start-run">Rehearse the workflow</button></div>'}</section>`;}

function templatesModal(){openModal('Start with a real business journey','SIX FICTIONAL EXAMPLES',`<p class="lead">Each example shares the same designer. Your drafts are retained when you switch processes. “Fresh v2 sample” keeps your previous draft in version history.</p><div class="template-grid">${Object.entries(TEMPLATES).map(([k,t])=>`<div class="template-choice"><button class="template-option" data-template="${k}"><span>${t.icon}</span><strong>${esc(t.name)}</strong><p>${esc(t.desc)}</p><small>${k==='onboarding'||k==='offboarding'?'Try independent parallel tasks':k==='payroll'?'Try a decision table':'Try conditional reviews'} →</small></button><button class="text-btn fresh-sample" data-fresh-template="${k}">Fresh v2 sample ↗</button></div>`).join('')}</div>`);}
function useTemplate(key,fresh=false){save();if(fresh&&persisted.drafts[key]){const number=Math.max(0,...persisted.versions.filter(v=>v.draft.template===key).map(v=>v.number||0))+1;persisted.versions.unshift({id:uid('version'),number,note:'Draft preserved before loading fresh sample',draft:clone(persisted.drafts[key]),at:new Date().toISOString()})}state.template=key;state.draft=!fresh&&persisted.drafts[key]?migrate(persisted.drafts[key]):freshDraft(key);state.history=[];state.redo=[];state.run=null;state.suite=null;state.selected='manager';state.facts={...SAMPLE,amount:TEMPLATES[key].value};state.mode='design';save();closeModal();render();}
let modalData=null;
function scopeModal(reset=true){if(reset)modalData=clone({name:draft().name,event:draft().event,scope:draft().scope});const x=modalData;openModal('When should this workflow apply?','PROCESS SETTINGS',`<div class="scope-grid"><section>${field('Process name',input('name',x.name,'text','data-scope-top="name"'))}${field('Start event',input('event',x.event,'text','data-scope-top="event"'))}${field('Company boundary (sample)',input('company',x.scope.company,'text','data-scope-prop="company"'))}<div class="mini-note">Domain: ${esc(TEMPLATES[state.template].domain)}<br>Adapter model: ${esc(TEMPLATES[state.template].model)}<br>Production eligibility must enforce actual company boundaries.</div></section><section><h3>Record eligibility</h3><p class="hint">Use typed conditions to keep this process focused.</p>${field('Match',select('match',[['all','All conditions'],['any','Any condition']],x.scope.match,'data-scope-prop="match"'))}${x.scope.rules.map((r,i)=>`<div class="rule-row">${select('field',[['amount',TEMPLATES[state.template].numeric],['department','Department'],['country','Country']],r.field,`data-scope-rule="${i}" data-prop="field"`)}${select('op',r.field==='amount'?[['gt','>'],['gte','≥'],['lt','<'],['eq','=']]:[['eq','is'],['ne','is not']],r.op,`data-scope-rule="${i}" data-prop="op"`)}${input('value',r.value,r.field==='amount'?'number':'text',`data-scope-rule="${i}" data-prop="value"`)}<button class="icon-btn danger" data-remove-rule="${i}" aria-label="Remove filter">×</button></div>`).join('')}<button class="button white" data-action="add-filter">＋ Add filter</button><div class="mini-note">${x.scope.rules.length?'These filters are evaluated before any work starts.':'No filters: every example in the sample company is eligible.'}</div></section></div><div class="modal-actions"><button class="button primary" data-action="apply-scope">Save settings</button></div>`);}
function stageModal(index){modalData={index,...clone(draft().stages[index])};openModal('Give the phase meaning','PHASE SETTINGS',`${field('Phase label',input('phase',modalData.name,'text','id="phase-name"'))}${field('Illustrative record label',input('label',modalData.state,'text','id="phase-state"'))}<p class="lead">Phases group work for people. They are not executable steps and do not define native business states.</p><div class="modal-actions">${index&& !nodes().some(n=>n.stage===index)?'<button class="button white danger" data-action="delete-stage">Remove empty phase</button>':''}<button class="button white" data-action="new-stage">＋ Add phase after this</button><button class="button primary" data-action="save-stage">Save phase</button></div>`);}
function addModal(key,stage){state.addTarget={key,stage};const suggested=current().type==='trigger'?['approval','input','branch']:HUMAN.includes(current().type)?['branch','email','parallel']:['task','state','email'];openModal('What happens next?','CONTEXTUAL SUGGESTIONS',`<p class="lead">Add work to ${key==='main'?esc(draft().stages[stage].name):'this named route'}. Groups can contain several steps, including other groups.</p><div class="suggestion-row">${suggested.map(k=>`<button class="suggestion" data-add-type="${k}">${icons(k)}<b>${TYPES[k].name}</b><span>${TYPES[k].description}</span></button>`).join('')}</div><div class="section-label">ALL BUILDING BLOCKS</div><div class="block-grid">${Object.entries(TYPES).filter(([k])=>!['trigger','condition'].includes(k)).map(([k,t])=>`<button class="palette-item" data-add-type="${k}">${icons(k)}<span>${t.name}</span></button>`).join('')}</div><button class="button white" data-action="components">Browse reusable components →</button>`);}
function policyModal(reset=true){if(reset)modalData={id:current().id,rows:clone(current().rows)};const n=byId(draft(),modalData.id),d=clone(draft());byId(d,n.id).rows=modalData.rows;const problems=issues(d).filter(i=>i.id===n.id);openModal('Readable policy. Predictable decisions.','UNIQUE MATCH DECISION TABLE',`<p class="lead">A row resolves the reviewer; the approval step can use “Policy result”. Minimum is inclusive, maximum is exclusive. Leave maximum empty for no upper limit.</p><div class="policy-table-wrap"><table class="detail-table policy-table"><thead><tr><th>Department</th><th>Amount ≥</th><th>Amount &lt;</th><th>Reviewer</th><th></th></tr></thead><tbody>${modalData.rows.map((r,i)=>`<tr><td>${select('department',['Any','Operations','Engineering','Finance','People'],r.department,`data-policy="${i}" data-prop="department"`)}</td><td>${input('min',r.min,'number',`data-policy="${i}" data-prop="min" min="0"`)}</td><td>${input('max',r.max??'','number',`data-policy="${i}" data-prop="max" placeholder="No limit" min="0"`)}</td><td>${select('owner',PEOPLE.filter(x=>!['System','Policy result','Employee'].includes(x)),r.owner,`data-policy="${i}" data-prop="owner"`)}</td><td><button class="icon-btn danger" data-remove-policy="${i}" aria-label="Remove policy row">×</button></td></tr>`).join('')}</tbody></table></div><button class="button white" data-action="add-policy">＋ Add row</button><div class="mini-note">No match → ${esc(n.fallback)}. Multiple matches → blocked by validation.</div>${problems.map(p=>`<div class="review-error">${esc(p.text)}</div>`).join('')||'<div class="review-success">✓ No overlapping ranges found.</div>'}<div class="modal-actions"><button class="button primary" data-action="apply-policy">Apply decision table</button></div>`);}
function saveComponentModal(id){const n=byId(draft(),id);modalData={id};openModal('Turn this group into a reusable component','BROWSER-LOCAL LIBRARY',`${field('Component name',input('name',n.component?.name||n.title,'text','id="component-name"'))}<p class="lead">Save ${descendants(draft(),id).length} steps as a versioned snapshot. Reusing it creates a pinned copy. Publishing a newer version will not silently change existing workflows.</p><div class="modal-actions"><button class="button primary" data-action="confirm-component">Save component version</button></div>`);}
function componentsModal(){const cs=persisted.components;openModal('Build once. Reuse with confidence.','VERSIONED COMPONENT LIBRARY',`<p class="lead">Components are local to this browser. Insertions keep their chosen version; you can inspect or edit the copied steps.</p>${cs.length?cs.map(c=>`<div class="history-item"><div><b>${esc(c.name)} · v${c.version}</b><p>${c.nodes.length} steps · ${new Date(c.at).toLocaleString()}</p></div><button class="button primary" data-insert-component="${c.id}">Insert pinned copy</button></div>`).join(''):'<div class="blank">Select a route or parallel group, then choose “Save as component”.<br>Or add the starter below.</div>'}<div class="recommendation"><strong>Starter: two-person review</strong><p>Manager review followed by Finance sign-off, grouped as one reusable process.</p><button class="button white" data-action="starter-component">Add starter component</button></div>`);}
function insertComponent(id){const c=persisted.components.find(c=>c.id===id),target=state.addTarget||{key:'main',stage:current().stage},stage=containers(draft()).find(x=>x.key===target.key)?.parent?.stage??target.stage;change(()=>{const copy=clone(c.nodes),map=Object.fromEntries(copy.map(n=>[n.id,uid('step')]));copy.forEach(n=>{n.id=map[n.id];n.stage=stage;delete n.pos;if(n.branches)n.branches.forEach(b=>{b.id=uid('route');b.steps=b.steps.map(k=>map[k])});if(n.steps)n.steps=n.steps.map(k=>map[k]);if(n.body)n.body=n.body.replace(/\{\{step\.([^}]+)\.result\}\}/g,(match,k)=>map[k]?`{{step.${map[k]}.result}}`:match)});const wrapper=makeNode('subprocess',stage);wrapper.title=c.name;wrapper.component={name:c.name,version:c.version,id:c.id};wrapper.steps=[map[c.root]];nodes().push(...copy,wrapper);const box=containers(draft()).find(x=>x.key===target.key)||containers(draft())[0];if(box.key==='main'){const idx=box.ids.findLastIndex(k=>byId(draft(),k).stage<=stage)+1;box.ids.splice(Math.max(1,idx),0,wrapper.id)}else box.ids.push(wrapper.id);state.selected=wrapper.id;});state.addTarget=null;closeModal();toast('Pinned component inserted. Configure any process-specific values.');}
function participantPreview(){const n=current(),actor=actorFor(n,{facts:state.facts});openModal('Preview the person’s next action','PARTICIPANT EXPERIENCE',`<div class="participant"><div class="participant-top"><span class="avatar">◉</span><div><small>${esc(actor.role)}</small><h3>${esc(n.title)}</h3><p>${esc(actor.name)} · due in ${n.due} working days</p></div></div><div class="sample-record"><span>FICTIONAL RECORD</span><b>Priya Shah</b><p>${n.owner==='IT team'?'Equipment request · financial details hidden':`${esc(TEMPLATES[state.template].numeric)}: ${state.facts.amount}`} · ${esc(state.facts.department)}</p></div>${n.type==='input'?field(n.fieldLabel+(n.required?' *':''),`<textarea placeholder="${esc(n.prompt)}" disabled></textarea>`):'<p class="lead">A short task, the information this person needs, and clear actions.</p>'}<div class="mini-note">This design preview does not submit an action. Rehearse to try role restrictions, approval, rejection and requesting changes.</div><button class="button primary" data-action="start-run">Try the complete experience →</button></div>`);}
function dataModal(){const n=current();openModal('Every value has a type and a source','TYPED DATA MAPPING',`<p class="lead">Only record values and outputs guaranteed to precede this step are offered. Results from an optional route are not assumed to exist after a join.</p><table class="detail-table"><thead><tr><th>Value</th><th>Type</th><th>Sample</th><th>Source</th></tr></thead><tbody>${availableTokens(draft(),n.id).map(t=>`<tr><td><b>${esc(t.label)}</b><br><code>{{${esc(t.key)}}}</code></td><td>${t.type}</td><td>${esc(t.value)}</td><td><button class="text-btn" data-select="${t.source}">Go to source ↗</button></td></tr>`).join('')}</tbody></table>`);}
function peopleModal(){openModal('Responsibility, cover and permission','CONNECTED, BUT DISTINCT',`<p class="lead">A responsibility chooses the person. Approval cover can substitute a valid delegate. Access policies still decide what that person can see and do.</p><table class="detail-table"><thead><tr><th>Responsibility</th><th>Fictional person</th><th>Sample policy</th></tr></thead><tbody>${Object.entries(PERSONS).map(([role,name])=>`<tr><td>${role}</td><td>${name}</td><td>${role==='Their manager'?'Alex Lee covers Maya while valid. Expired cover blocks.':role==='IT team'?'Equipment task only; financial detail hidden in preview.':'Only an assigned task is actionable in rehearsal.'}</td></tr>`).join('')}</tbody></table><div class="recommendation">Use existing role resolution and <code>biz_access</code> checks in production. Approval delegation must never silently grant broader record access.</div><button class="button primary" data-action="facts">Try a cover or access scenario →</button>`);}
function versionModal(){if(definitionErrors().length){setMode('review');return;}openModal('Save a version you can return to','IMMUTABLE LOCAL SNAPSHOT',`${field('What changed?',input('note','','text','id="version-note" placeholder="e.g. Added evidence for high-value claims"'))}<p class="lead">Saved versions are read-only snapshots in this browser. Restoring creates a draft. This does not activate a workflow or change any business record.</p><div class="modal-actions"><button class="button primary" data-action="confirm-version">Save local version</button></div>`);}
function exportDraft(){const data={schema:SCHEMA,definition:clone(draft()),graph:compile(draft()),notice:'Design prototype only. Not a production workflow import.'};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download='payobook-'+state.template+'-workflow-v2.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Definition and compiled graph exported.');}

document.addEventListener('click',e=>{
 const b=e.target.closest('button,a');if(!b)return;
 if(b.matches('.brand')){e.preventDefault();setMode('design');return;}
 if(b.dataset.view){state.view=b.dataset.view;state.mode='design';render();return;}
 if(b.dataset.mode){setMode(b.dataset.mode);return;}
 if(b.dataset.node&&!dragged){state.selected=b.dataset.node;render();return;}
 if(b.dataset.select){selectNode(b.dataset.select);return;}
 if(b.dataset.pickView){state.view=b.dataset.pickView;setMode('design');return;}
 if(b.dataset.research){research(b.dataset.research);return;}
 if(b.dataset.benchmark){benchmarkCategory=b.dataset.benchmark;research('benchmarks');return;}
 if(b.dataset.freshTemplate){useTemplate(b.dataset.freshTemplate,true);toast("Fresh v2 sample opened. Previous draft preserved in version history.");return;}
 if(b.dataset.template){useTemplate(b.dataset.template);return;}
 if(b.dataset.block){state.addTarget=null;addNode(b.dataset.block,'main',current().stage);return;}
 if(b.dataset.addType){addNode(b.dataset.addType,state.addTarget.key,state.addTarget.stage);state.addTarget=null;closeModal();return;}
 if(b.dataset.pending){state.pending=b.dataset.pending;state.viewer='Assigned participant';render();return;}
 if(b.dataset.respond){const answer=$('#participant-answer')?.value||'',result=respond(state.run,b.dataset.id,b.dataset.respond,answer);if(result.error){$('#participant-error').textContent=result.error;return;}rememberRun();render();return;}
 if(b.dataset.retry){retryRun(state.run,b.dataset.retry);rememberRun();render();return;}
 if(b.dataset.insertToken){const el=$('#email-message'),value=el.value,start=el.selectionStart,end=el.selectionEnd;change(()=>current().body=value.slice(0,start)+'{{'+b.dataset.insertToken+'}}'+value.slice(end));return;}
 if(b.dataset.removeRule!==undefined){modalData.scope.rules.splice(+b.dataset.removeRule,1);scopeModal(false);return;}
 if(b.dataset.removePolicy!==undefined){modalData.rows.splice(+b.dataset.removePolicy,1);policyModal(false);return;}
 if(b.dataset.insertComponent){insertComponent(b.dataset.insertComponent);return;}
 if(b.dataset.restore){const v=persisted.versions.find(v=>v.id===b.dataset.restore);change(()=>{state.draft=clone(v.draft);state.selected=nodes()[0].id;});toast('Snapshot restored as an editable draft.');return;}
 if(b.dataset.scenarioDetail!==undefined){const s=state.suite[+b.dataset.scenarioDetail];openModal(s.name,'SCENARIO OUTCOME COMPARISON',`<div class="review-${s.pass?'success':'error'}">${s.pass?'Outcome matches baseline.':'Outcome differs. Inspect whether the change is intentional.'}</div><details class="advanced"><summary>Compare expected and actual states</summary><pre>${esc(JSON.stringify(JSON.parse(s.expected),null,2))}</pre><pre>${esc(JSON.stringify(JSON.parse(s.actual),null,2))}</pre></details>${traceHTML({trace:s.trace})}`);return;}
 if(b.dataset.runDetail){const r=persisted.runs.find(r=>r.id===b.dataset.runDetail);openModal(r.draft.name,'SAVED REHEARSAL · '+r.status,traceHTML(r));return;}
 const action=b.dataset.action;
 if(action==='close'){closeModal();return;}
 if(action==='templates'||action==='recipe'){templatesModal();return;}
 if(action==='studio'){setMode('design');return;}
 if(action==='compare'){research();return;}
 if(action==='architecture'){research('architecture');return;}
 if(action==='help'){openModal('A few small moves. A complete workflow.','HOW TO USE THIS POC',`<div class="phase-list">${[['Build','Select a sample. Drag a block into a phase or a route. Click any step to configure it.'],['See','Switch between Journey, Canvas and Responsibility. Every view uses the same structured definition.'],['Rehearse','Enter sample facts, act as each participant and follow the trace. Try cover, denied access, rejection and email retries.'],['Review','Resolve readiness issues, compare scenario outcomes and save a local version. Export JSON to share the design.']].map(([h,p],i)=>`<div class="phase-item"><span>${i+1}</span><div><h3>${h}</h3><p>${p}</p></div></div>`).join('')}</div><p class="mini-note">Keyboard: Tab to controls; Enter to add and configure. Drag-and-drop also has click-to-add and move-up/down alternatives. Ctrl/Cmd+Z undoes definition edits. All data is fictional and saved locally.</p>`);return;}
 if(action==='people'){peopleModal();return;}
 if(action==='history'||action==='publish'||action==='readiness'){setMode('review');return;}
 if(action==='simulate'){setMode('rehearse');return;}
 if(action==='start-run'){startRun();return;}
 if(action==='facts'){factsModal();return;}
 if(action==='apply-facts'){const amount=+$('#fact-amount').value;if(!Number.isFinite(amount)||amount<0){toast('Enter a valid, nonnegative amount.');return;}state.facts={...state.facts,amount};['department','country','manager','access','actor','failure'].forEach(k=>state.facts[k]=$('#fact-'+k).value);startRun();return;}
 if(action==='resubmit'){const answer=$('#rework-answer').value.trim();if(!answer){toast('Describe the correction before resubmitting.');return;}logRun(state.run,{id:'trigger',title:'Requester correction'},answer);resubmitRun(state.run);rememberRun();render();return;}
 if(action==='save-scenario'){openModal('Keep this example for future changes','SAVED REGRESSION EXAMPLE',`${field('Example name',input('name','','text','id="scenario-name" placeholder="e.g. Finance exception for Operations"'))}<p class="lead">The simulator will finish the happy path automatically and save its outcome as the expected baseline for these inputs.</p><div class="modal-actions"><button class="button primary" data-action="confirm-scenario">Save example</button></div>`);return;}
 if(action==='confirm-scenario'){const name=$('#scenario-name').value.trim();if(!name){toast('Name the example.');return;}if(definitionErrors().length){toast('Resolve definition errors before saving an example.');return;}persisted.scenarios.push({id:uid('scenario'),template:state.template,name,facts:clone(state.facts),expected:outcomeSignature(autoRun(draft(),state.facts)),source:'Saved example'});save();closeModal();toast('Example saved with its expected outcome.');return;}
 if(action==='suite'){runSuite();return;}
 if(action==='scope'){scopeModal();return;}
 if(action==='add-filter'){modalData.scope.rules.push({field:'amount',op:'gt',value:1000});scopeModal(false);return;}
 if(action==='apply-scope'){if(!modalData.name.trim()||!modalData.event.trim()||!modalData.scope.company.trim()){toast('Complete the name, event and company.');return;}change(()=>Object.assign(draft(),clone(modalData)));closeModal();return;}
 if(action==='stage'){stageModal(+b.dataset.index);return;}
 if(action==='save-stage'){const name=$('#phase-name').value.trim(),label=$('#phase-state').value.trim();if(!name||!label){toast('Enter both phase labels.');return;}change(()=>draft().stages[modalData.index]={name,state:label});closeModal();return;}
 if(action==='new-stage'){const at=modalData.index+1;change(()=>{draft().stages.splice(at,0,{name:'New phase',state:'In progress'});nodes().forEach(n=>{if(n.stage>=at)n.stage++})});closeModal();return;}
 if(action==='delete-stage'){const at=modalData.index;change(()=>{draft().stages.splice(at,1);nodes().forEach(n=>{if(n.stage>at)n.stage--})});closeModal();return;}
 if(action==='add'){addModal(b.dataset.key,+b.dataset.stage);return;}
 if(action==='add-route'){change(()=>{const n=current(),r={id:uid('route'),label:n.type==='parallel'?'New parallel route':'New conditional route',steps:[]};if(n.type==='branch'){r.condition={field:'department',op:'eq',value:'Engineering'};n.branches.splice(n.branches.length-1,0,r)}else n.branches.push(r)});return;}
 if(action==='toggle-group'){const n=byId(draft(),b.dataset.id);n.collapsed=!n.collapsed;save();render();return;}
 if(action==='delete'){const n=current();if(n.type==='trigger')return;const ids=descendants(draft(),n.id);change(()=>{const c=containerFor(draft(),n.id);c.ids.splice(c.ids.indexOf(n.id),1);draft().nodes=nodes().filter(x=>!ids.includes(x.id));state.selected='trigger'});toast('Step and its children removed. Undo is available.');return;}
 if(action==='move-up'||action==='move-down'){const n=current(),c=containerFor(draft(),n.id),i=c.ids.indexOf(n.id),next=i+(action==='move-up'?-1:1);if(next<0||next>=c.ids.length||c.ids[next]==='trigger'||byId(draft(),c.ids[next]).stage!==n.stage){toast('Already at the edge of this phase or route.');return;}change(()=>{[c.ids[i],c.ids[next]]=[c.ids[next],c.ids[i]]});return;}
 if(action==='undo'){if(!state.history.length){toast('No changes to undo.');return;}state.redo.push(clone(draft()));state.draft=state.history.pop();state.run=null;state.suite=null;save();render();return;}
 if(action==='redo'){if(!state.redo.length)return;state.history.push(clone(draft()));state.draft=state.redo.pop();state.run=null;state.suite=null;save();render();return;}
 if(action==='export'){exportDraft();return;}
 if(action==='policy'){policyModal();return;}
 if(action==='add-policy'){modalData.rows.push({department:'Any',min:0,max:null,owner:'HR partner'});policyModal(false);return;}
 if(action==='apply-policy'){change(()=>byId(draft(),modalData.id).rows=clone(modalData.rows));closeModal();return;}
 if(action==='save-component'){saveComponentModal(b.dataset.id||current().id);return;}
 if(action==='confirm-component'){const name=$('#component-name').value.trim();if(!name){toast('Name this component.');return;}const ids=descendants(draft(),modalData.id),version=Math.max(0,...persisted.components.filter(c=>c.name===name).map(c=>c.version))+1;persisted.components.unshift({id:uid('component'),name,version,root:modalData.id,nodes:clone(nodes().filter(n=>ids.includes(n.id))),at:new Date().toISOString()});save();componentsModal();return;}
 if(action==='components'){componentsModal();return;}
 if(action==='starter-component'){const root=makeNode('subprocess',1),a=makeNode('approval',1),b=makeNode('approval',1);root.title='Two-person review';a.title='Manager review';b.title='Finance sign-off';b.owner='Finance approver';root.steps=[a.id,b.id];persisted.components.unshift({id:uid('component'),name:'Two-person review',version:1,root:root.id,nodes:[root,a,b],at:new Date().toISOString()});save();componentsModal();return;}
 if(action==='participant'){participantPreview();return;}
 if(action==='data'){dataModal();return;}
 if(action==='save-version'){versionModal();return;}
 if(action==='confirm-version'){const number=Math.max(0,...persisted.versions.filter(v=>v.draft.template===state.template).map(v=>v.number||0))+1;persisted.versions.unshift({id:uid('version'),number,note:$('#version-note').value.trim()||'Workflow snapshot',draft:clone(draft()),at:new Date().toISOString()});save();closeModal();state.suite=null;render();toast('Version '+number+' saved locally.');return;}
 if(action==='tour-onboarding'){useTemplate('onboarding');startRun();return;}
 if(action==='zoom-in'||action==='zoom-out'||action==='zoom-reset'||action==='fit'||action==='layout'){if(action==='layout')nodes().forEach(n=>delete n.pos);else if(action==='fit')state.zoom=Math.max(.25,Math.min(1,($('#workarea').clientWidth-30)/canvasSize.w));else state.zoom=action==='zoom-reset'?.7:Math.max(.25,Math.min(1.5,state.zoom+(action==='zoom-in'?.1:-.1)));render();return;}
});
document.addEventListener('change',e=>{const el=e.target;
 if(el.dataset.edit){const key=el.dataset.edit,n=current();change(()=>{if(key==='stage'){setStage(n.id,+el.value);draft().order.sort((a,b)=>byId(draft(),a).stage-byId(draft(),b).stage)}else n[key]=el.type==='checkbox'?el.checked:['due','hours','retry'].includes(key)?Number(el.value):el.value});return;}
 if(el.dataset.event){change(()=>draft().event=el.value);return;}
 if(el.dataset.route!==undefined){change(()=>{const b=current().branches[+el.dataset.route],key=el.dataset.routeProp;if(key==='label')b.label=el.value;else{b.condition[key]=el.value;if(key==='field'){b.condition.op=el.value==='amount'?'gt':'eq';b.condition.value=el.value==='amount'?1000:el.value==='country'?'Australia':'Operations';}}});return;}
 if(el.hasAttribute('data-viewer')){state.viewer=el.value;renderRehearsal();return;}
 if(el.dataset.scopeTop){modalData[el.dataset.scopeTop]=el.value;return;}
 if(el.dataset.scopeProp){modalData.scope[el.dataset.scopeProp]=el.value;return;}
 if(el.dataset.scopeRule!==undefined){const r=modalData.scope.rules[+el.dataset.scopeRule];r[el.dataset.prop]=el.value;if(el.dataset.prop==='field'){r.op=el.value==='amount'?'gt':'eq';r.value=el.value==='amount'?1000:el.value==='country'?'Australia':'Operations';scopeModal(false)}return;}
 if(el.dataset.policy!==undefined){const key=el.dataset.prop;modalData.rows[+el.dataset.policy][key]=['min','max'].includes(key)?el.value===''&&key==='max'?null:Number(el.value):el.value;policyModal(false);return;}
});
document.addEventListener('input',e=>{if(e.target.hasAttribute('data-palette-search')){state.search=e.target.value;renderPalette();bindDrag()}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'&&!['INPUT','TEXTAREA'].includes(e.target.tagName)){e.preventDefault();$(`[data-action="${e.shiftKey?'redo':'undo'}"]`)?.click()}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
render();save();
